#[tokio::test]
async fn port_forward_marker_renders_in_table() {
    use ratatui::Terminal;
    use ratatui::backend::TestBackend;

    let listener = std::net::TcpListener::bind((std::net::Ipv4Addr::LOCALHOST, 0)).unwrap();
    let port = listener.local_addr().unwrap().port();
    drop(listener);
    let (mut app, _rx) = test_app();
    app.switch_kind("services");
    apply(
        &mut app,
        json!({
            "apiVersion": "v1", "kind": "Service",
            "metadata": {"name": "alpha", "namespace": "default", "resourceVersion": "1"},
            "spec": {"ports": [{"port": port}]}
        }),
    );
    apply(
        &mut app,
        json!({
            "apiVersion": "v1", "kind": "Service",
            "metadata": {"name": "beta", "namespace": "default", "resourceVersion": "1"},
            "spec": {"ports": [{"port": 8080}]}
        }),
    );
    app.table_state.select(Some(0));

    // Start a forward on the first row (alpha) so it gets the marker.
    app.request_port_forward();
    app.handle_key(press(KeyCode::Enter)).unwrap();
    assert_eq!(app.port_forwards.len(), 1);
    assert_eq!(app.port_forwards[0].target, "svc/alpha");

    let mut term = Terminal::new(TestBackend::new(120, 32)).unwrap();
    term.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
    let buffer = term.backend().buffer().clone();
    let screen: String = (0..buffer.area.height)
        .map(|y| {
            (0..buffer.area.width)
                .map(|x| buffer[(x, y)].symbol())
                .collect::<String>()
        })
        .collect::<Vec<_>>()
        .join("\n");

    // The forwarded row "alpha" should have a ● before its name.
    let alpha_line = screen
        .lines()
        .find(|l| l.contains("alpha"))
        .expect("alpha row in screen");
    assert!(
        alpha_line.contains("●"),
        "expected ● marker on forwarded row, got: {alpha_line}"
    );

    // The non-forwarded row "beta" should NOT have a ●.
    let beta_line = screen
        .lines()
        .find(|l| l.contains("beta"))
        .expect("beta row in screen");
    assert!(
        !beta_line.contains("●"),
        "unexpected ● on non-forwarded row, got: {beta_line}"
    );
}

#[test]
fn forward_context_matching_and_validation() {
    let f = crate::config::Forward {
        name: "x".into(),
        target: "svc/x".into(),
        namespace: "ns".into(),
        ports: "8080:80".into(),
        autostart: true,
        contexts: vec!["home".into()],
    };
    assert!(f.matches_context("home"));
    assert!(!f.matches_context("prod"));
    let all = crate::config::Forward {
        contexts: vec![],
        ..f.clone()
    };
    assert!(all.matches_context("anything"));

    let warnings = crate::config::forward_warnings(&[
        crate::config::Forward {
            name: "".into(),
            ..f.clone()
        },
        crate::config::Forward {
            name: "badports".into(),
            ports: "eighty:80".into(),
            ..f.clone()
        },
        f.clone(),
        f.clone(), // duplicate name
    ]);
    assert_eq!(warnings.len(), 3, "{warnings:?}");
    assert!(warnings.iter().any(|w| w.contains("empty name")));
    assert!(warnings.iter().any(|w| w.contains("not LOCAL:REMOTE")));
    assert!(warnings.iter().any(|w| w.contains("duplicate name")));
}

#[tokio::test]
async fn pod_status_changes_keep_column_positions_stable() {
    use ratatui::{Terminal, backend::TestBackend};

    for width in [80, 120, 180] {
        let (mut app, _rx) = test_app();
        app.handle_key(press(KeyCode::Char(':'))).unwrap();
        for c in "pods".chars() {
            app.handle_key(press(KeyCode::Char(c))).unwrap();
        }
        app.handle_key(press(KeyCode::Enter)).unwrap();
        assert_eq!(app.kind_plural, "pods");

        let mut terminal = Terminal::new(TestBackend::new(width, 24)).unwrap();
        let mut initial_columns = None;
        for status in [
            "Pending",
            "ContainerCreating",
            "Running",
            "CrashLoopBackOff",
            "CreateContainerConfigError",
            "Running",
        ] {
            let state = if status == "Running" {
                json!({"running": {}})
            } else {
                json!({"waiting": {"reason": status}})
            };
            apply(
                &mut app,
                json!({
                    "apiVersion": "v1", "kind": "Pod",
                    "metadata": {"name": "example", "namespace": "default"},
                    "status": {
                        "phase": "Running",
                        "containerStatuses": [{
                            "ready": status == "Running", "restartCount": 0,
                            "state": state
                        }]
                    }
                }),
            );
            terminal
                .draw(|frame| crate::ui::draw(frame, &mut app))
                .unwrap();
            let hit = app.table_hit.borrow().clone().unwrap();
            let status_index = app
                .display_headers()
                .iter()
                .position(|header| header == "STATUS")
                .unwrap();
            let &(start, end, _) = hit
                .cols
                .iter()
                .find(|(_, _, index)| *index == status_index)
                .unwrap();
            assert_eq!(end - start, 26, "status width at terminal width {width}");
            let status_cell: String = (start..end)
                .map(|x| terminal.backend().buffer()[(x, hit.rows_y)].symbol())
                .collect();
            assert_eq!(status_cell.trim(), status);
            if let Some(ref columns) = initial_columns {
                assert_eq!(&hit.cols, columns, "columns moved for {status} at {width}");
            } else {
                initial_columns = Some(hit.cols);
            }
        }
    }
}

#[tokio::test]
async fn cordoned_node_statuses_keep_readiness_colors() {
    use crate::theme;
    use ratatui::{Terminal, backend::TestBackend, style::Color};

    fn cell_text(terminal: &Terminal<TestBackend>, start: u16, end: u16, y: u16) -> String {
        (start..end)
            .map(|x| terminal.backend().buffer()[(x, y)].symbol())
            .collect::<String>()
            .trim()
            .to_string()
    }

    fn cell_color(terminal: &Terminal<TestBackend>, start: u16, end: u16, y: u16) -> Color {
        (start..end)
            .map(|x| &terminal.backend().buffer()[(x, y)])
            .find(|cell| !cell.symbol().trim().is_empty())
            .map(|cell| cell.fg)
            .unwrap()
    }

    let (mut app, _rx) = test_app();
    app.handle_key(press(KeyCode::Char(':'))).unwrap();
    for c in "nodes".chars() {
        app.handle_key(press(KeyCode::Char(c))).unwrap();
    }
    app.handle_key(press(KeyCode::Enter)).unwrap();
    assert_eq!(app.kind_plural, "nodes");

    let node = |name: &str, ready: Option<&str>| {
        let conditions = ready.map_or_else(
            || json!([]),
            |status| json!([{"type": "Ready", "status": status}]),
        );
        json!({
            "apiVersion": "v1", "kind": "Node",
            "metadata": {"name": name},
            "spec": {"unschedulable": true},
            "status": {"conditions": conditions}
        })
    };
    apply(&mut app, node("a-ready", Some("True")));
    apply(&mut app, node("b-not-ready", Some("False")));
    apply(&mut app, node("c-unknown", None));

    // Select the last row so the first two retain their semantic foregrounds.
    app.handle_key(press(KeyCode::End)).unwrap();
    let mut terminal = Terminal::new(TestBackend::new(160, 24)).unwrap();
    terminal
        .draw(|frame| crate::ui::draw(frame, &mut app))
        .unwrap();
    let hit = app.table_hit.borrow().clone().unwrap();
    let headers = app.display_headers();
    let column_range = |header: &str| {
        let index = headers.iter().position(|h| h == header).unwrap();
        hit.cols
            .iter()
            .find(|(_, _, i)| *i == index)
            .map(|&(start, end, _)| (start, end))
            .unwrap()
    };
    let (name_start, name_end) = column_range("NAME");
    let (status_start, status_end) = column_range("STATUS");
    let ready_y = hit.rows_y;
    let not_ready_y = ready_y + 1;
    let unknown_y = ready_y + 2;

    assert_eq!(
        cell_text(&terminal, name_start, name_end, ready_y),
        "a-ready"
    );
    assert_eq!(
        cell_text(&terminal, status_start, status_end, ready_y),
        "Ready,SchedulingDisabled"
    );
    assert_eq!(
        cell_color(&terminal, name_start, name_end, ready_y),
        theme::blue()
    );
    assert_eq!(
        cell_color(&terminal, status_start, status_end, ready_y),
        theme::yellow()
    );

    assert_eq!(
        cell_text(&terminal, name_start, name_end, not_ready_y),
        "b-not-ready"
    );
    assert_eq!(
        cell_text(&terminal, status_start, status_end, not_ready_y),
        "NotReady,SchedulingDisabled"
    );
    assert_eq!(
        cell_color(&terminal, name_start, name_end, not_ready_y),
        theme::red()
    );
    assert_eq!(
        cell_color(&terminal, status_start, status_end, not_ready_y),
        theme::red()
    );

    // Move selection away from Unknown and redraw before checking its colors.
    app.handle_key(press(KeyCode::Home)).unwrap();
    terminal
        .draw(|frame| crate::ui::draw(frame, &mut app))
        .unwrap();
    assert_eq!(
        cell_text(&terminal, status_start, status_end, unknown_y),
        "Unknown,SchedulingDisabled"
    );
    assert_eq!(
        cell_color(&terminal, name_start, name_end, unknown_y),
        theme::blue()
    );
    assert_eq!(
        cell_color(&terminal, status_start, status_end, unknown_y),
        theme::overlay1()
    );
}

#[tokio::test]
async fn scrolling_pods_keeps_column_positions_stable() {
    use ratatui::{Terminal, backend::TestBackend};

    for (width, height) in [(80, 24), (120, 32), (180, 48), (220, 52)] {
        let (mut app, _rx) = test_app();
        app.switch_kind("pods");
        app.namespace.clear();
        for i in 0..90 {
            let namespace = if i == 0 { "a-long-namespace" } else { "z" };
            let name = if i == 89 {
                "pod-89-with-a-much-longer-name-than-the-other-pods".to_string()
            } else {
                format!("pod-{i:02}")
            };
            apply(
                &mut app,
                json!({
                    "apiVersion": "v1", "kind": "Pod",
                    "metadata": {"name": name, "namespace": namespace},
                    "status": {"phase": "Running"}
                }),
            );
        }
        app.handle_key(press(KeyCode::Home)).unwrap();
        let mut terminal = Terminal::new(TestBackend::new(width, height)).unwrap();
        terminal.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
        let initial = app.table_hit.borrow().clone().unwrap();
        let header = |terminal: &Terminal<TestBackend>| -> String {
            (0..width)
                .map(|x| terminal.backend().buffer()[(x, initial.header_y)].symbol())
                .collect()
        };
        let initial_header = header(&terminal);

        for key in [KeyCode::Down, KeyCode::Up] {
            for _ in 0..89 {
                app.handle_key(press(key)).unwrap();
                terminal.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
                assert_eq!(
                    app.table_hit.borrow().as_ref().unwrap().cols,
                    initial.cols,
                    "columns moved at {width}x{height}, offset {}",
                    app.table_state.offset()
                );
                assert_eq!(header(&terminal), initial_header);
            }
            if key == KeyCode::Down {
                assert!(app.table_state.offset() > 0);
                assert_eq!(app.table_state.selected(), Some(89));
            }
        }
        assert_eq!(app.table_state.offset(), 0);
    }
}

#[tokio::test]
async fn table_widths_follow_offscreen_updates_filters_and_view_changes() {
    use ratatui::{Terminal, backend::TestBackend};

    let (mut app, _rx) = test_app();
    app.switch_kind("pods");
    let pod = |i: usize, node: &str| {
        json!({
            "apiVersion": "v1", "kind": "Pod",
            "metadata": {"name": format!("pod-{i:02}"), "namespace": "default"},
            "spec": {"nodeName": node},
            "status": {"phase": "Running"}
        })
    };
    for i in 0..40 {
        apply(&mut app, pod(i, "node"));
    }
    app.handle_key(press(KeyCode::Char('w'))).unwrap();
    let mut terminal = Terminal::new(TestBackend::new(180, 24)).unwrap();
    terminal.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
    let initial = app.table_hit.borrow().clone().unwrap().cols;

    apply(
        &mut app,
        pod(39, "node-with-a-much-longer-name-outside-the-viewport"),
    );
    terminal.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
    let updated = app.table_hit.borrow().clone().unwrap().cols;
    assert_ne!(updated, initial, "an updated row must change the widths");
    app.handle_key(press(KeyCode::End)).unwrap();
    terminal.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
    assert_eq!(app.table_hit.borrow().as_ref().unwrap().cols, updated);

    app.handle_key(press(KeyCode::Char('/'))).unwrap();
    for c in "pod-00".chars() {
        app.handle_key(press(KeyCode::Char(c))).unwrap();
    }
    app.handle_key(press(KeyCode::Enter)).unwrap();
    terminal.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
    assert_eq!(app.row_count(), 1);
    assert_eq!(app.table_hit.borrow().as_ref().unwrap().cols, initial);

    app.handle_key(press(KeyCode::Char('w'))).unwrap();
    terminal.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
    assert!(!app.display_headers().iter().any(|h| h == "NODE"));
    assert_eq!(
        app.table_hit.borrow().as_ref().unwrap().cols.len(),
        app.display_headers().len()
    );
}

#[tokio::test]
async fn mouse_click_selects_row_header_click_sorts_wheel_moves() {
    use crossterm::event::{MouseButton, MouseEvent, MouseEventKind};
    use ratatui::Terminal;
    use ratatui::backend::TestBackend;

    let (mut app, _rx) = test_app();
    app.switch_kind("pods");
    let pod = |name: &str, restarts: i64| {
        json!({
            "apiVersion": "v1", "kind": "Pod",
            "metadata": {"name": name, "namespace": "default"},
            "status": {"phase": "Running", "containerStatuses":
                [{"ready": true, "restartCount": restarts, "state": {"running": {}}}]}
        })
    };
    apply(&mut app, pod("a", 5));
    apply(&mut app, pod("b", 1));
    app.table_state.select(Some(0));

    // A frame must render first — that's what records the hit geometry.
    let mut term = Terminal::new(TestBackend::new(120, 32)).unwrap();
    term.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
    let hit = app.table_hit.borrow().clone().expect("geometry recorded");

    let click = |column: u16, row: u16| MouseEvent {
        kind: MouseEventKind::Down(MouseButton::Left),
        column,
        row,
        modifiers: KeyModifiers::NONE,
    };

    // Click the second data row → it becomes the selection.
    app.handle_mouse(click(hit.x_min + 3, hit.rows_y + 1))
        .unwrap();
    assert_eq!(app.table_state.selected(), Some(1));

    // Click the RESTARTS header → sort by it; again → flip direction.
    let ridx = app
        .display_headers()
        .to_vec()
        .iter()
        .position(|h| h == "RESTARTS")
        .unwrap();
    let (sx, _, _) = hit
        .cols
        .iter()
        .copied()
        .find(|(_, _, i)| *i == ridx)
        .unwrap();
    app.handle_mouse(click(sx, hit.header_y)).unwrap();
    assert_eq!(app.sort_column, Some(ridx));
    assert!(!app.sort_desc);
    app.handle_mouse(click(sx, hit.header_y)).unwrap();
    assert!(app.sort_desc);

    // Wheel scroll maps to the mode's own up/down keys (3 per notch).
    app.table_state.select(Some(0));
    app.handle_mouse(MouseEvent {
        kind: MouseEventKind::ScrollDown,
        column: 0,
        row: 0,
        modifiers: KeyModifiers::NONE,
    })
    .unwrap();
    assert_eq!(app.table_state.selected(), Some(1), "clamped at the end");

    // A click outside the table (e.g. the header panel) is ignored.
    app.handle_mouse(click(0, 0)).unwrap();
    assert_eq!(app.table_state.selected(), Some(1));
}

#[tokio::test]
async fn horizontal_scroll_keeps_names_and_moves_content_without_resizing() {
    use crossterm::event::{MouseButton, MouseEvent, MouseEventKind};
    use ratatui::{Terminal, backend::TestBackend};

    for all_namespaces in [false, true] {
        let (mut app, _rx) = test_app();
        app.switch_kind("pods");
        if all_namespaces {
            app.namespace.clear();
        }
        apply(
            &mut app,
            json!({
                "apiVersion": "v1", "kind": "Pod",
                "metadata": {"name": "web", "namespace": "default"},
                "spec": {"nodeName": "node-abcdefghijklmnopqrstuvwxyz-0123456789-long-value"},
                "status": {"phase": "Running"}
            }),
        );
        app.handle_key(press(KeyCode::Char('w'))).unwrap();
        app.handle_key(press(KeyCode::Home)).unwrap();
        let mut term = Terminal::new(TestBackend::new(80, 24)).unwrap();
        term.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
        assert!(app.col_scroll_max > 5);
        let initial = term.backend().buffer().clone();
        let hit = app.table_hit.borrow().clone().unwrap();
        let title = |term: &Terminal<TestBackend>| -> String {
            (hit.x_min..hit.x_max)
                .map(|x| term.backend().buffer()[(x, hit.header_y - 1)].symbol())
                .collect()
        };
        assert!(title(&term).contains('→'));
        assert!(!title(&term).contains('←'));
        let anchored = usize::from(all_namespaces) + 1;
        let frozen_end = hit.cols[anchored].0;
        app.handle_key(press(KeyCode::Left)).unwrap();
        assert_eq!(app.col_offset, 0);
        app.handle_key(press(KeyCode::Right)).unwrap();
        term.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
        assert_eq!(app.col_offset, 5);
        assert!(title(&term).contains('←'));
        assert!(title(&term).contains('→'));
        let moved = app.table_hit.borrow().clone().unwrap();
        assert_eq!(&hit.cols[..anchored], &moved.cols[..anchored]);
        for y in [hit.header_y, hit.rows_y] {
            for x in hit.x_min..frozen_end {
                assert_eq!(
                    initial[(x, y)].symbol(),
                    term.backend().buffer()[(x, y)].symbol()
                );
            }
            for x in frozen_end..hit.x_max.saturating_sub(5) {
                assert_eq!(
                    initial[(x + 5, y)].symbol(),
                    term.backend().buffer()[(x, y)].symbol()
                );
            }
        }
        app.handle_key(press(KeyCode::Left)).unwrap();
        term.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
        assert_eq!(term.backend().buffer(), &initial);
        app.handle_key(press(KeyCode::Right)).unwrap();
        term.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
        let &(start, _, index) = moved.cols.last().unwrap();
        app.handle_mouse(MouseEvent {
            kind: MouseEventKind::Down(MouseButton::Left),
            column: start,
            row: moved.header_y,
            modifiers: KeyModifiers::NONE,
        })
        .unwrap();
        assert_eq!(app.sort_column, Some(index));
        app.handle_key(press(KeyCode::Left)).unwrap();
        assert_eq!(app.col_offset, 0);
        for _ in 0..100 {
            app.handle_key(press(KeyCode::Right)).unwrap();
        }
        term.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
        assert_eq!(app.col_offset, app.col_scroll_max);
        assert_eq!(
            app.table_hit
                .borrow()
                .as_ref()
                .unwrap()
                .cols
                .last()
                .unwrap()
                .2,
            app.display_headers().len() - 1
        );
        assert!(title(&term).contains('←'));
        assert!(!title(&term).contains('→'));
        let at_end = app.col_offset;
        app.handle_key(press(KeyCode::Right)).unwrap();
        assert_eq!(app.col_offset, at_end);
        app.handle_key(press(KeyCode::Char('w'))).unwrap();
        assert_eq!(app.col_offset, 0);
    }
}

#[tokio::test]
async fn horizontal_scroll_stops_when_columns_fit_and_resets_after_resize() {
    use ratatui::{Terminal, backend::TestBackend};

    let (mut app, _rx) = test_app();
    app.switch_kind("pods");
    let mut term = Terminal::new(TestBackend::new(180, 24)).unwrap();
    term.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
    assert_eq!(app.col_scroll_max, 0);
    let before = term.backend().buffer().clone();
    app.handle_key(press(KeyCode::Right)).unwrap();
    term.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
    assert_eq!(app.col_offset, 0);
    assert_eq!(term.backend().buffer(), &before);

    term.backend_mut().resize(45, 24);
    term.autoresize().unwrap();
    term.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
    app.handle_key(press(KeyCode::Right)).unwrap();
    assert!(app.col_offset > 0);
    term.backend_mut().resize(180, 24);
    term.autoresize().unwrap();
    term.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
    assert_eq!(app.col_offset, 0);
    assert_eq!(app.col_scroll_max, 0);
}

#[tokio::test]
async fn horizontal_scroll_clips_wide_characters_at_both_edges() {
    use ratatui::{Terminal, backend::TestBackend};

    let (mut app, _rx) = test_app();
    install_views(
        &mut app,
        r#"
        [[views."cert-manager.io/v1/certificates".columns]]
        name = "VALUE"
        path = "/spec/value"
        width = 40
        align = "right"
    "#,
    );
    app.switch_kind("certificates");
    apply(
        &mut app,
        json!({
            "apiVersion": "cert-manager.io/v1", "kind": "Certificate",
            "metadata": {"name": "web", "namespace": "default"},
            "spec": {"value": "界".repeat(20)}
        }),
    );
    app.handle_key(press(KeyCode::Home)).unwrap();
    let mut term = Terminal::new(TestBackend::new(30, 24)).unwrap();
    term.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
    for _ in 0..4 {
        app.handle_key(press(KeyCode::Right)).unwrap();
        let rendered = term
            .draw(|f| crate::ui::draw(f, &mut app))
            .unwrap()
            .buffer
            .clone();
        let hit = app.table_hit.borrow().clone().unwrap();
        let &(start, end, _) = hit.cols.iter().find(|c| c.2 == 1).unwrap();
        for x in start..end {
            let source = app.col_offset + usize::from(x - start);
            let expected = if source.is_multiple_of(2) && x + 1 < end {
                "界"
            } else {
                " "
            };
            assert_eq!(rendered[(x, hit.rows_y)].symbol(), expected);
            // A terminal does not write the second half of a wide character.
            if source.is_multiple_of(2) || x == start {
                assert_eq!(term.backend().buffer()[(x, hit.rows_y)].symbol(), expected);
            }
        }
    }
    for width in [1, 2, 3, 4, 8] {
        term.backend_mut().resize(width, 24);
        term.autoresize().unwrap();
        term.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
        app.handle_key(press(KeyCode::Right)).unwrap();
        term.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
    }
}

#[tokio::test]
async fn document_views_release_mouse_capture_for_text_selection() {
    let (mut app, _rx) = test_app();
    assert!(app.wants_mouse_capture(), "table keeps capture");

    // Every full-screen text view releases capture so click-drag selects text
    // natively (#133), including the filter overlays that keep it on screen.
    // Logs included: the alternate-scroll bursts that used to throw the view
    // off (#152) are repaired in `crate::altscroll`, not by holding capture.
    for mode in [
        Mode::Detail,
        Mode::Diff,
        Mode::Events,
        Mode::Logs,
        Mode::Help,
        Mode::DocFilter,
        Mode::LogFilter,
    ] {
        app.mode = mode;
        assert!(!app.wants_mouse_capture(), "{mode:?} releases capture");
    }

    // Interactive pickers and dashboards still want clicks/wheel captured.
    for mode in [Mode::Table, Mode::Namespaces, Mode::Pulse, Mode::Confirm] {
        app.mode = mode;
        assert!(app.wants_mouse_capture(), "{mode:?} keeps capture");
    }
}

#[tokio::test]
async fn notify_toggles_a_background_watch_per_object() {
    let (mut app, _rx) = test_app();
    app.switch_kind("pods");
    apply(
        &mut app,
        json!({"apiVersion": "v1", "kind": "Pod",
               "metadata": {"name": "web", "namespace": "default"}}),
    );
    app.table_state.select(Some(0));

    assert!(app.run_palette_command("notify"));
    assert_eq!(app.notify_tasks.len(), 1);
    assert!(app.notify_tasks.contains_key("pods/default/web"));
    assert!(app.flash.contains("notify on"), "{}", app.flash);

    // Same command on the same row toggles it off.
    assert!(app.run_palette_command("notify"));
    assert!(app.notify_tasks.is_empty());
    assert!(app.flash.contains("notify off"), "{}", app.flash);
}

#[tokio::test]
async fn notify_survives_view_switches() {
    let (mut app, _rx) = test_app();
    app.switch_kind("pods");
    apply(
        &mut app,
        json!({"apiVersion": "v1", "kind": "Pod",
               "metadata": {"name": "web", "namespace": "default"}}),
    );
    app.table_state.select(Some(0));
    assert!(app.run_palette_command("notify"));
    assert_eq!(app.notify_tasks.len(), 1);
    let epoch = app.notify_epoch;

    // bump_generation (any view switch) aborts self.tasks — the notify watch
    // must not be among them.
    app.switch_kind("services");
    assert_eq!(app.notify_tasks.len(), 1);
    assert!(!app.notify_tasks["pods/default/web"].is_finished());
    assert_eq!(app.notify_epoch, epoch);
    app.handle_msg(Msg::Notify {
        epoch,
        text: "pod/web: Ready True → False".into(),
    });
    assert_eq!(
        app.take_notification().as_deref(),
        Some("pod/web: Ready True → False")
    );
}

#[tokio::test]
async fn context_switch_stops_notifications_and_drops_stale_messages() {
    let (mut app, _rx) = test_app();
    app.switch_kind("pods");
    apply(
        &mut app,
        json!({"apiVersion": "v1", "kind": "Pod",
               "metadata": {"name": "web", "namespace": "default"}}),
    );
    app.handle_key(press(KeyCode::Home)).unwrap();
    for ch in ":notify".chars() {
        app.handle_key(press(KeyCode::Char(ch))).unwrap();
    }
    app.handle_key(press(KeyCode::Enter)).unwrap();
    assert_eq!(app.notify_tasks.len(), 1);
    let old_epoch = app.notify_epoch;
    let old_task = app.notify_tasks["pods/default/web"].abort_handle();

    app.handle_msg(Msg::Notify {
        epoch: old_epoch,
        text: "pod/web: old cluster".into(),
    });
    assert_eq!(app.pending_notify.len(), 1);

    pick_context(&mut app, "west");
    assert_eq!(app.notify_tasks.len(), 1);
    assert_eq!(app.notify_epoch, old_epoch);
    land_context(&mut app, "west");
    tokio::task::yield_now().await;
    assert!(app.notify_tasks.is_empty());
    assert!(old_task.is_finished());
    assert_eq!(app.notify_epoch, old_epoch + 1);
    assert_eq!(app.take_notification(), None);

    let flash = app.flash.clone();
    app.handle_msg(Msg::Notify {
        epoch: old_epoch,
        text: "pod/web: late old cluster".into(),
    });
    assert_eq!(app.flash, flash);
    assert_eq!(app.take_notification(), None);

    apply(
        &mut app,
        json!({"apiVersion": "v1", "kind": "Pod",
               "metadata": {"name": "web", "namespace": "default"}}),
    );
    app.handle_key(press(KeyCode::Home)).unwrap();
    for ch in ":notify".chars() {
        app.handle_key(press(KeyCode::Char(ch))).unwrap();
    }
    app.handle_key(press(KeyCode::Enter)).unwrap();
    assert!(app.notify_tasks.contains_key("pods/default/web"));
}

