fn cronjob(name: &str) -> serde_json::Value {
    json!({
        "apiVersion": "batch/v1", "kind": "CronJob",
        "metadata": {"name": name, "namespace": "default", "uid": "cj-uid-1"},
        "spec": {
            "schedule": "0 * * * *",
            "suspend": false,
            "jobTemplate": {
                "metadata": {
                    "labels": {"app": name},
                    "annotations": {"team": "platform"}
                },
                "spec": {
                    "template": {"spec": {
                        "containers": [{"name": "main", "image": "busybox"}],
                        "restartPolicy": "Never"
                    }}
                }
            }
        }
    })
}

