        let warnings = app.configure_keys(&config.keys);
        assert!(warnings.is_empty(), "{warnings:?}");

        app.handle_key(press(KeyCode::Char(':'))).unwrap();
        app.handle_key(press(KeyCode::Char('-'))).unwrap();
