#[tokio::test]
async fn sorted_order_updates_when_an_object_changes() {
    // Sort keys are cached per resourceVersion; an update must invalidate the
    // changed row's cached key (via invalidate_row) and re-sort with the new
    // value, while unchanged rows reuse theirs.
    let (mut app, _rx) = test_app();
    app.switch_kind("pods");
    let pod = |name: &str, rv: &str, restarts: i64| {
        json!({
            "apiVersion": "v1", "kind": "Pod",
            "metadata": {"name": name, "namespace": "default", "resourceVersion": rv},
            "status": {
                "phase": "Running",
                "containerStatuses": [
                    {"ready": true, "restartCount": restarts, "state": {"running": {}}}
                ]
            }
        })
    };
    apply(&mut app, pod("a", "1", 5));
    apply(&mut app, pod("b", "1", 1));
    apply(&mut app, pod("c", "1", 9));
    assert_eq!(app.display_headers().to_vec()[3], "RESTARTS");
    app.sort_column = Some(3);
    app.invalidate_rows();
    let names = |app: &App| -> Vec<String> {
        app.rows()
            .iter()
            .map(|o| o.metadata.name.clone().unwrap())
            .collect()
    };
    assert_eq!(names(&app), ["b", "a", "c"]); // 1, 5, 9

    apply(&mut app, pod("b", "2", 20));
    assert_eq!(names(&app), ["a", "c", "b"]); // 5, 9, 20

    // Changing the sort column must not reuse keys computed for the old one.
    assert_eq!(app.display_headers().to_vec()[0], "NAME");
    app.sort_column = Some(0);
    app.invalidate_rows();
    assert_eq!(names(&app), ["a", "b", "c"]);
}

#[tokio::test]
async fn age_sort_new_pod_not_lost_among_stale_cached_keys() {
    // AGE sort keys are cached by (header, resourceVersion), but depend on
    // `now`. A new pod triggers a rebuild at a later `now`; unchanged pods
    // reuse stale keys with a smaller age, so the new pod sorts after them.
    let (mut app, _rx) = test_app();
    app.switch_kind("pods");
    let age_idx = app
        .display_headers()
        .to_vec()
        .iter()
        .position(|h| h == "AGE")
        .unwrap();

    let pod = |name: &str, created: &str, rv: &str| {
        json!({
            "apiVersion": "v1", "kind": "Pod",
            "metadata": {
                "name": name, "namespace": "default",
                "resourceVersion": rv, "creationTimestamp": created
            },
            "status": {"phase": "Running"}
        })
    };

    // Two pods created years ago.
    apply(&mut app, pod("old-a", "2020-01-01T00:00:00Z", "1"));
    apply(&mut app, pod("old-b", "2021-01-01T00:00:00Z", "1"));
    app.sort_column = Some(age_idx);
    app.invalidate_rows();
    assert_eq!(row_names(&app), ["old-b", "old-a"]);

    // Inject stale sort keys: simulate a cache built at an earlier `now`.
    {
        let mut cache = app.rows_cache.borrow_mut();
        cache.sort_keys.insert(
            Rc::from("default/old-a"),
            SortKeyEntry {
                header: "AGE".into(),
                resource_version: Some("1".into()),
                key: SortKey::Num(10.0),
            },
        );
        cache.sort_keys.insert(
            Rc::from("default/old-b"),
            SortKeyEntry {
                header: "AGE".into(),
                resource_version: Some("1".into()),
                key: SortKey::Num(10.0),
            },
        );
    }

    // A new pod created 30 s ago: its fresh age (30) is larger than the stale
    // cached age (10), so with the bug it sorts after the old pods.
    let now = Timestamp::now().as_second();
    let created = Timestamp::from_second(now - 30).unwrap().to_string();
    apply(&mut app, pod("new-pod", &created, "1"));

    // Correct ascending order: new-pod (30 s) before old-b (5 y) before
    // old-a (6 y).
    assert_eq!(row_names(&app), ["new-pod", "old-b", "old-a"]);
}

#[tokio::test]
async fn age_sort_rebuilds_periodically_without_watch_events() {
    // AGE sort keys change every second without a watch event; the cache
    // must rebuild once per second to keep them fresh.
    let (mut app, _rx) = test_app();
    app.switch_kind("pods");
    apply(
        &mut app,
        json!({"apiVersion": "v1", "kind": "Pod",
               "metadata": {"name": "p", "namespace": "default",
                            "creationTimestamp": "2020-01-01T00:00:00Z"}}),
    );
    let age_idx = app
        .display_headers()
        .to_vec()
        .iter()
        .position(|h| h == "AGE")
        .unwrap();
    app.sort_column = Some(age_idx);
    app.invalidate_rows();
    let _ = row_names(&app);

    // Simulate one second passing without a watch event.
    let stale;
    {
        let mut cache = app.rows_cache.borrow_mut();
        cache.filter_second -= 1;
        stale = cache.filter_second;
        assert!(!cache.dirty);
    }

    let _ = row_names(&app);

    assert_ne!(
        app.rows_cache.borrow().filter_second,
        stale,
        "AGE sort should rebuild once per second"
    );
}

#[tokio::test]
async fn sort_picker_picks_toggles_and_clears() {
    let (mut app, _rx) = test_app();
    app.switch_kind("pods");

    // `S` opens the picker: default entry pinned first and selected (no sort).
    app.handle_key(press(KeyCode::Char('S'))).unwrap();
    assert_eq!(app.mode, Mode::SortPicker);
    assert_eq!(app.filtered_sort_entries().to_vec()[0], DEFAULT_SORT_LABEL);
    assert_eq!(app.sort_picker_state.selected(), Some(0));

    // Type-to-filter fuzzy-matches columns; the cursor lands on the best
    // match (right after the pinned default) and enter selects it, ascending.
    for c in "rst".chars() {
        app.handle_key(press(KeyCode::Char(c))).unwrap();
    }
    assert_eq!(app.filtered_sort_entries().to_vec()[1], "RESTARTS");
    assert_eq!(app.sort_picker_state.selected(), Some(1));
    app.handle_key(press(KeyCode::Enter)).unwrap();
    assert_eq!(app.mode, Mode::Table);
    let restarts = app
        .display_headers()
        .to_vec()
        .iter()
        .position(|h| h == "RESTARTS");
    assert!(restarts.is_some());
    assert_eq!(app.sort_column, restarts);
    assert!(!app.sort_desc);
    assert!(app.flash.contains("RESTARTS") && app.flash.contains("asc"));

    // Reopening lands on the active column; re-picking it inverts direction.
    app.handle_key(press(KeyCode::Char('S'))).unwrap();
    assert_eq!(app.sort_picker_state.selected(), restarts.map(|i| i + 1));
    app.handle_key(press(KeyCode::Enter)).unwrap();
    assert_eq!(app.sort_column, restarts);
    assert!(app.sort_desc);

    // Picking a different column resets to ascending.
    app.handle_key(press(KeyCode::Char('S'))).unwrap();
    app.sort_picker_state.select(Some(1)); // NAME (first column)
    app.handle_key(press(KeyCode::Enter)).unwrap();
    assert_eq!(app.sort_column, Some(0));
    assert!(!app.sort_desc);

    // The pinned default entry clears the sort.
    app.handle_key(press(KeyCode::Char('S'))).unwrap();
    app.sort_picker_state.select(Some(0));
    app.handle_key(press(KeyCode::Enter)).unwrap();
    assert_eq!(app.sort_column, None);
    assert!(!app.sort_desc);
}

#[tokio::test]
async fn sort_choice_is_remembered_per_kind_across_view_switches() {
    let (mut app, _rx) = test_app();
    app.switch_kind("pods");

    // Pick RESTARTS via the picker, then invert with `I`.
    app.handle_key(press(KeyCode::Char('S'))).unwrap();
    for c in "rst".chars() {
        app.handle_key(press(KeyCode::Char(c))).unwrap();
    }
    app.handle_key(press(KeyCode::Enter)).unwrap();
    app.handle_key(press(KeyCode::Char('I'))).unwrap();
    let restarts = app
        .display_headers()
        .to_vec()
        .iter()
        .position(|h| h == "RESTARTS");
    assert_eq!(app.sort_column, restarts);
    assert!(app.sort_desc);
    assert_eq!(app.sort_memory.get("pods"), Some(("RESTARTS".into(), true)));

    // A kind with no memory starts unsorted; the pods memory is untouched.
    app.switch_kind("deployments");
    assert_eq!(app.sort_column, None);
    assert_eq!(app.sort_memory.get("pods"), Some(("RESTARTS".into(), true)));

    // Coming back restores column and direction.
    app.switch_kind("pods");
    assert_eq!(
        app.sort_column,
        app.display_headers()
            .to_vec()
            .iter()
            .position(|h| h == "RESTARTS")
    );
    assert!(app.sort_desc);

    // A header click is remembered too.
    app.switch_kind("deployments");
    let ready = app
        .display_headers()
        .to_vec()
        .iter()
        .position(|h| h == "READY")
        .unwrap();
    app.sort_column = Some(ready);
    app.sort_desc = false;
    app.remember_sort();
    assert_eq!(
        app.sort_memory.get("deployments"),
        Some(("READY".into(), false))
    );

    // Picking the pinned default forgets the kind's memory.
    app.switch_kind("pods");
    app.handle_key(press(KeyCode::Char('S'))).unwrap();
    app.sort_picker_state.select(Some(0));
    app.handle_key(press(KeyCode::Enter)).unwrap();
    assert_eq!(app.sort_column, None);
    assert_eq!(app.sort_memory.get("pods"), None);
    app.switch_kind("deployments");
    app.switch_kind("pods");
    assert_eq!(app.sort_column, None);
}

#[tokio::test]
async fn wildcard_sort_is_the_fallback_for_resource_views() {
    let (mut app, _rx) = test_app();
    install_views(
        &mut app,
        r#"
        [views."*"]
        sort = "AGE:desc"
        [views.pods]
        [views.services]
        sort = "NAME:asc"
        "#,
    );
    for (resource, header, desc) in [
        ("pods", "AGE", true),
        ("deployments", "AGE", true),
        ("services", "NAME", false),
    ] {
        palette(&mut app, resource);
        assert_eq!(app.kind_plural, resource);
        assert_eq!(
            app.sort_column,
            app.display_headers().iter().position(|h| h == header)
        );
        assert!(app.sort_column.is_some());
        assert_eq!(app.sort_desc, desc);
    }

    palette(&mut app, "pods");
    app.handle_key(press(KeyCode::Char('I'))).unwrap();
    palette(&mut app, "services");
    palette(&mut app, "pods");
    assert!(!app.sort_desc, "saved choice has priority over the default");
}

