fn waiting_logs_app(code: u16, reason: &str) -> (App, Receiver<Msg>, Arc<AtomicU64>) {
    let (mut app, rx) = test_app();
    app.switch_kind("pods");
    apply(
        &mut app,
        json!({"apiVersion": "v1", "kind": "Pod",
            "metadata": {"name": "pending", "namespace": "default"},
            "spec": {"containers": [{"name": "app", "image": "test"}]},
            "status": {"phase": "Pending"}}),
    );
    app.table_state.select(Some(0));
    let requests = Arc::new(AtomicU64::new(0));
    let seen = requests.clone();
    let message = if code == 400 && reason != "invalid container" {
        format!("container \"app\" in pod \"pending\" is waiting to start: {reason}")
    } else {
        reason.to_owned()
    };
    app.cluster.client = kube::Client::new(
        tower::service_fn(move |request: http::Request<kube::client::Body>| {
            assert_eq!(
                request.uri().path(),
                "/api/v1/namespaces/default/pods/pending/log"
            );
            let attempt = seen.fetch_add(1, Ordering::SeqCst);
            let (status, body) = if attempt < 2 {
                (
                    code,
                    json!({"kind": "Status", "apiVersion": "v1",
                    "status": "Failure", "message": message,
                    "reason": "BadRequest", "code": code})
                    .to_string(),
                )
            } else {
                (200, "started\n".to_owned())
            };
            async move {
                Ok::<_, std::convert::Infallible>(
                    http::Response::builder()
                        .status(status)
                        .body(http_body_util::Full::new(hyper::body::Bytes::from(body)))
                        .unwrap(),
                )
            }
        }),
        "default",
    );
    (app, rx, requests)
}

#[tokio::test]
async fn logs_keep_view_and_restore_selection() {
    let (mut app, _rx) = test_app();
    app.switch_kind("pods");
    for n in ["a", "b", "c"] {
        apply(
            &mut app,
            json!({"apiVersion": "v1", "kind": "Pod",
                   "metadata": {"name": n, "namespace": "default"}}),
        );
    }
    app.table_state.select(Some(1)); // "b"
    assert_eq!(app.selected().unwrap().metadata.name.as_deref(), Some("b"));
    let gen_before = app.generation;

    app.handle_key(press(KeyCode::Char('l'))).unwrap(); // open logs
    assert_eq!(app.mode, Mode::Logs);
    assert_eq!(app.rows().len(), 3, "underlying view stays populated");

    app.handle_key(press(KeyCode::Esc)).unwrap(); // back to table
    assert_eq!(app.mode, Mode::Table);
    assert_eq!(
        app.generation, gen_before,
        "view watch was not torn down/restarted"
    );
    assert_eq!(app.rows().len(), 3, "rows were not blanked + reloaded");
    assert_eq!(
        app.selected().unwrap().metadata.name.as_deref(),
        Some("b"),
        "cursor returned to the same pod"
    );
}

#[tokio::test]
async fn namespace_switcher_known_rows_do_not_block_palette_fetch_retry() {
    let (mut app, mut rx) = test_app();
    let (requests, mut request_rx) = mpsc::unbounded_channel();
    let mut attempts = 0;
    app.cluster.client = kube::Client::new(
        tower::service_fn(move |request: http::Request<kube::client::Body>| {
            assert_eq!(request.uri().path(), "/api/v1/namespaces");
            attempts += 1;
            requests.send(attempts).unwrap();
            let (status, body) = if attempts == 1 {
                (
                    503,
                    json!({
                        "kind": "Status", "apiVersion": "v1", "status": "Failure",
                        "reason": "ServiceUnavailable", "message": "try again", "code": 503
                    }),
                )
            } else {
                (
                    200,
                    json!({
                        "kind": "NamespaceList", "apiVersion": "v1", "metadata": {},
                        "items": [{"metadata": {"name": "staging"}}]
                    }),
                )
            };
            async move {
                Ok::<_, std::convert::Infallible>(
                    http::Response::builder()
                        .status(status)
                        .body(http_body_util::Full::new(hyper::body::Bytes::from(
                            body.to_string(),
                        )))
                        .unwrap(),
                )
            }
        }),
        "default",
    );
    app.namespace = "prod".into();
    app.handle_key(press(KeyCode::Char('n'))).unwrap();
    assert_eq!(
        app.filtered_namespaces().as_ref(),
        &["<all>", "default", "prod"]
    );
    assert_eq!(
        tokio::time::timeout(Duration::from_secs(2), request_rx.recv())
            .await
            .unwrap(),
        Some(1)
    );
    assert!(app.ns_list.is_empty());

    app.handle_key(press(KeyCode::Esc)).unwrap();
    app.handle_key(press(KeyCode::Char(':'))).unwrap();
    assert_eq!(app.filtered_namespaces().as_ref(), &["<all>"]);
    assert_eq!(
        tokio::time::timeout(Duration::from_secs(2), request_rx.recv())
            .await
            .unwrap(),
        Some(2)
    );
    let message = tokio::time::timeout(Duration::from_secs(2), rx.recv())
        .await
        .unwrap()
        .unwrap();
    assert!(matches!(&message, Msg::Namespaces { .. }));
    app.handle_msg(message);
    for c in "pods sta".chars() {
        app.handle_key(press(KeyCode::Char(c))).unwrap();
    }
    let suggestion = app.cmd_suggestions.first().expect("namespace suggestion");
    assert_eq!(suggestion.kind, SuggestKind::Namespace);
    assert_eq!(suggestion.label, "staging");
    assert_eq!(app.ns_list, ["<all>", "staging"]);
}

