#[tokio::test]
async fn namespace_switcher_labels_current_and_context_default() {
    use ratatui::{Terminal, backend::TestBackend};

    for (namespace, expected) in [
        ("default", "default (current, context default)"),
        ("prod", "prod (current)"),
        ("", "<all> (current)"),
    ] {
        let (mut app, _rx) = test_app();
        app.namespace = namespace.into();
        app.handle_key(press(KeyCode::Char('n'))).unwrap();
        assert_eq!(
            app.filtered_namespaces()[app.ns_state.selected().unwrap()],
            if namespace.is_empty() {
                "<all>"
            } else {
                namespace
            }
        );
        let mut terminal = Terminal::new(TestBackend::new(80, 24)).unwrap();
        terminal.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
        let text = terminal
            .backend()
            .buffer()
            .content
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(text.contains(expected), "{text}");
        if namespace != "default" {
            assert!(text.contains("default (context default)"), "{text}");
        }

        app.handle_key(press(KeyCode::Char('d'))).unwrap();
        terminal.draw(|f| crate::ui::draw(f, &mut app)).unwrap();
        let text = terminal
            .backend()
            .buffer()
            .content
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(text.contains(expected), "{text}");
        app.handle_key(press(KeyCode::Esc)).unwrap();
        app.handle_key(press(KeyCode::Esc)).unwrap();
        app.handle_key(press(KeyCode::Char('n'))).unwrap();
        app.handle_key(press(KeyCode::Enter)).unwrap();
        assert_eq!(app.namespace, namespace);
    }
}

#[tokio::test]
async fn namespace_switcher_pins_all_and_fuzzy_filters() {
    let (mut app, _rx) = test_app();
    app.ns_list = vec![
        "<all>".into(),
        "default".into(),
        "kube-system".into(),
        "prod".into(),
    ];
    // No filter: <all> first, then the rest.
    assert_eq!(app.filtered_namespaces().to_vec()[0], "<all>");
    assert_eq!(app.filtered_namespaces().to_vec().len(), 4);

    // Fuzzy filter (subsequence) keeps <all> pinned on top.
    app.ns_filter = "sys".into();
    let f = app.filtered_namespaces().to_vec();
    assert_eq!(f[0], "<all>");
    assert!(f.contains(&"kube-system".to_string()));
    assert!(!f.contains(&"default".to_string()));

    // Typing a name that matches nothing real → Enter takes it verbatim.
    app.ns_filter = "team-x".into();
    app.mode = Mode::Namespaces;
    app.handle_key(press(KeyCode::Enter)).unwrap();
    assert_eq!(app.namespace, "team-x");
}

