#[test]
fn join_selectors_merges_drill_and_filter() {
    let some = |s: &str| Some(s.to_string());
    assert_eq!(join_selectors(&None, &None), None);
    assert_eq!(join_selectors(&some("a=b"), &None), some("a=b"));
    assert_eq!(join_selectors(&None, &some("c=d")), some("c=d"));
    assert_eq!(join_selectors(&some("a=b"), &some("c=d")), some("a=b,c=d"));
}

// ----- config reload (`:reload`) and validation (`:config`) ---------------

fn write_config(dir: &std::path::Path, text: &str) {
    std::fs::create_dir_all(dir).unwrap();
    std::fs::write(dir.join("config.toml"), text).unwrap();
}

#[tokio::test]
async fn reload_updates_columns_in_the_open_view() {
    let dir = std::env::temp_dir().join(format!("sofka-reload-columns-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    let (mut app, _rx) = test_app();
    app.config = crate::config::ConfigLoader::from_dir(Some(dir.clone()));
    palette(&mut app, "pods");
    apply(
        &mut app,
        json!({"apiVersion": "v1", "kind": "Pod",
            "metadata": {"name": "api", "namespace": "default"},
            "status": {"phase": "Running"}}),
    );
    app.table_state.select(Some(0));
    let original = app.snapshot_table();
    let generation = app.generation;
    write_config(
        &dir,
        r#"[views."v1/pods"]
columns = [
    { name = "%CPU/R", metric = "cpu-request-utilization" },
    { name = "%CPU/L", metric = "cpu-limit-utilization" },
    { name = "%MEM/R", metric = "memory-request-utilization" },
    { name = "%MEM/L", metric = "memory-limit-utilization" },
]
"#,
    );
    palette(&mut app, "reload");
    for header in ["%CPU/R", "%CPU/L", "%MEM/R", "%MEM/L"] {
        assert!(app.display_headers().iter().any(|h| h == header));
    }
    assert!(app.config_warnings.is_empty(), "{:?}", app.config_warnings);
    assert_eq!(app.generation, generation);
    assert_eq!(app.kind_plural, "pods");
    assert_eq!(app.table_state.selected(), Some(0));
    assert_eq!(app.rows().len(), 1);

    write_config(
        &dir,
        r#"[views."v1/pods"]
replace = true
columns = [
    { name = "NAME", builtin = "NAME" },
    { name = "PHASE", path = "/status/phase" },
    { name = "BAD", metric = "unknown" },
]
"#,
    );
    palette(&mut app, "reload");
    assert_eq!(app.display_headers().to_vec(), ["NAME", "PHASE"]);
    assert_eq!(app.snapshot_table().1, vec![vec!["api", "Running"]]);
    assert!(app.config_warnings.iter().any(|w| w.contains("unknown")));

    write_config(&dir, "[views");
    palette(&mut app, "reload");
    assert!(app.flash_err);
    assert_eq!(app.display_headers().to_vec(), ["NAME", "PHASE"]);

    std::fs::remove_file(dir.join("config.toml")).unwrap();
    palette(&mut app, "reload");
    assert_eq!(app.snapshot_table(), original);
    assert!(app.config_warnings.is_empty());
    std::fs::remove_dir_all(dir).unwrap();
}

#[tokio::test]
async fn reload_applies_config_changes_live() {
    let dir = std::env::temp_dir().join(format!("sofka-app-reload-ok-{}", std::process::id()));
    write_config(&dir, "[aliases]\ndep = \"deployments\"\n");
    let (mut app, _rx) = test_app();
    app.config = crate::config::ConfigLoader::from_dir(Some(dir.clone()));

    app.reload_config();
    assert_eq!(
        app.user_aliases.get("dep").map(String::as_str),
        Some("deployments")
    );
    assert!(app.cluster.resolve("dep").is_some(), "alias registered");
    assert!(!app.flash_err);
    assert!(app.config_warnings.is_empty());

    // Edit the file on disk: `:reload` picks up new aliases, mode, and skin
    // without a restart. (The skin is the built-in default so the write to
    // the global palette is value-identical — parallel tests read it.)
    write_config(
        &dir,
        "readonly = true\n[aliases]\nks = \"services\"\n[skin]\nname = \"catppuccin-mocha\"\n",
    );
    app.reload_config();
    assert!(app.readonly);
    assert_eq!(
        app.user_aliases.get("ks").map(String::as_str),
        Some("services")
    );
    assert!(!app.user_aliases.contains_key("dep"), "aliases replaced");
    assert_eq!(app.session_skin.as_deref(), Some("catppuccin-mocha"));
    assert_eq!(app.active_skin.as_deref(), Some("catppuccin-mocha"));
    assert!(app.flash.contains("config reloaded"), "{}", app.flash);
    assert!(!app.flash_err);

    std::fs::remove_dir_all(&dir).unwrap();
}

#[tokio::test]
async fn mouse_scroll_lines_sets_rows_per_wheel_notch() {
    use crossterm::event::{MouseEvent, MouseEventKind};

    let dir = std::env::temp_dir().join(format!("sofka-app-wheel-{}", std::process::id()));
    write_config(&dir, "mouse_scroll_lines = 1\n");
    let (mut app, _rx) = test_app();
    app.config = crate::config::ConfigLoader::from_dir(Some(dir.clone()));
    app.reload_config();
    assert!(app.config_warnings.is_empty());

    app.switch_kind("pods");
    for name in ["a", "b", "c", "d", "e"] {
        apply(
            &mut app,
            json!({
                "apiVersion": "v1", "kind": "Pod",
                "metadata": {"name": name, "namespace": "default"},
                "status": {"phase": "Running"}
            }),
        );
    }
    app.table_state.select(Some(0));
    let notch = MouseEvent {
        kind: MouseEventKind::ScrollDown,
        column: 0,
        row: 0,
        modifiers: KeyModifiers::NONE,
    };

    app.handle_mouse(notch).unwrap();
    assert_eq!(app.table_state.selected(), Some(1), "one row per notch");

    // `0` is treated as one row and reported as a config warning; an unset
    // value restores the default of three and clears the warning.
    write_config(&dir, "mouse_scroll_lines = 0\n");
    app.reload_config();
    assert_eq!(
        app.config_warnings,
        vec!["mouse_scroll_lines: 0 is not allowed — using 1".to_string()]
    );
    app.handle_mouse(notch).unwrap();
    assert_eq!(app.table_state.selected(), Some(2));

    // Values above the maximum are capped so one wheel event cannot stall
    // the UI; the list boundary still stops the selection.
    write_config(&dir, "mouse_scroll_lines = 65535\n");
    app.reload_config();
    assert_eq!(
        app.config_warnings,
        vec!["mouse_scroll_lines: 65535 is above the maximum of 100 — using 100".to_string()]
    );
    assert_eq!(app.mouse_scroll_lines, 100);
    app.handle_mouse(notch).unwrap();
    assert_eq!(app.table_state.selected(), Some(4), "stops at the last row");

    write_config(&dir, "");
    app.reload_config();
    assert!(app.config_warnings.is_empty());
    app.table_state.select(Some(0));
    app.handle_mouse(notch).unwrap();
    assert_eq!(
        app.table_state.selected(),
        Some(3),
        "default three per notch"
    );

    std::fs::remove_dir_all(&dir).unwrap();
}

#[tokio::test]
async fn wheel_that_dismisses_a_confirm_does_not_scroll_the_table_beneath() {
    use crossterm::event::{MouseEvent, MouseEventKind};

    let (mut app, _rx) = test_app();
    app.switch_kind("pods");
    for name in ["a", "b", "c", "d", "e"] {
        apply(
            &mut app,
            json!({
                "apiVersion": "v1", "kind": "Pod",
                "metadata": {"name": name, "namespace": "default"},
                "status": {"phase": "Running"}
            }),
        );
    }
    app.table_state.select(Some(0));
    app.handle_key(KeyEvent::new(KeyCode::Char('d'), KeyModifiers::CONTROL))
        .unwrap();
    assert_eq!(app.mode, Mode::Confirm);

    // With the default of three steps, the first step cancels the confirm and
    // the remaining two must not move the selection in the table.
    app.handle_mouse(MouseEvent {
        kind: MouseEventKind::ScrollDown,
        column: 0,
        row: 0,
        modifiers: KeyModifiers::NONE,
    })
    .unwrap();
    assert_eq!(app.mode, Mode::Table);
    assert_eq!(app.table_state.selected(), Some(0));
}

#[tokio::test]
async fn failed_reload_keeps_last_known_good_config() {
    let dir = std::env::temp_dir().join(format!("sofka-app-reload-bad-{}", std::process::id()));
    write_config(&dir, "readonly = true\n[aliases]\ndep = \"deployments\"\n");
    let (mut app, _rx) = test_app();
    app.config = crate::config::ConfigLoader::from_dir(Some(dir.clone()));
    app.reload_config();
    assert!(app.readonly);

    // A type error on disk: the running config must stay exactly as it was.
    write_config(&dir, "readonly = \"yes\"\n");
    app.reload_config();
    assert!(app.readonly, "previous readonly kept");
    assert_eq!(
        app.user_aliases.get("dep").map(String::as_str),
        Some("deployments")
    );
    assert!(app.flash_err);
    assert!(app.flash.contains("previous config kept"), "{}", app.flash);
    // The recorded error names the file, the offending key, and the problem.
    let err = &app.config_warnings[0];
    assert!(err.contains("config.toml"), "{err}");
    assert!(err.contains("readonly"), "{err}");
    assert!(err.contains("expected a boolean"), "{err}");

    // A later good edit recovers without a restart.
    write_config(&dir, "readonly = false\n");
    app.reload_config();
    assert!(!app.readonly);
    assert!(app.config_warnings.is_empty());

    std::fs::remove_dir_all(&dir).unwrap();
}

