#[tokio::test]
async fn drain_key_pins_uid_and_never_falls_back_to_delete() {
    for (code, missing, expected_error) in [
        (201, false, false),
        (404, true, false),
        (404, false, true),
        (405, false, true),
        (409, false, true),
        (429, false, true),
    ] {
        let (_, err, requests) = drain_api_case(json!([drain_managed_pod()]), code, missing).await;
        assert_eq!(
            err, expected_error,
            "eviction code {code}, missing {missing}"
        );
        assert!(!requests.iter().any(|r| r["method"] == "DELETE"));
        let eviction = requests.iter().find(|r| r["method"] == "POST").unwrap();
        assert_eq!(
            eviction["body"]["deleteOptions"]["preconditions"]["uid"],
            "original-uid"
        );
    }
}

