fn expression_workload(include_labels: bool) -> serde_json::Value {
    let mut workload = json!({"apiVersion":"apps/v1","kind":"Deployment",
        "metadata":{"name":"web","namespace":"default","uid":"workload-uid"},
        "spec":{"replicas":1,"selector":{"matchExpressions":[
            {"key":"tier","operator":"In","values":["frontend","api"]},
            {"key":"environment","operator":"NotIn","values":["test"]},
            {"key":"enabled","operator":"Exists"},
            {"key":"disabled","operator":"DoesNotExist"}
        ]}}, "status":{"replicas":1,"readyReplicas":1,"updatedReplicas":1}});
    if include_labels {
        workload["spec"]["selector"]["matchLabels"] = json!({"app":"web"});
    }
    workload
}

#[tokio::test]
async fn workload_enter_preserves_all_selector_requirements() {
    for include_labels in [false, true] {
        let (mut app, _rx) = test_app();
        app.switch_kind("deployments");
        apply(&mut app, expression_workload(include_labels));
        app.table_state.select(Some(0));
        app.handle_key(press(KeyCode::Enter)).unwrap();
        assert_eq!(app.kind_plural, "pods");
        let expected = if include_labels {
            "app=web,tier in (api,frontend),environment notin (test),enabled,!disabled"
        } else {
            "tier in (api,frontend),environment notin (test),enabled,!disabled"
        };
        assert_eq!(app.labels.as_deref(), Some(expected));
    }
}

#[tokio::test]
async fn workload_explain_requests_complete_expression_selector() {
    let (mut app, mut rx) = test_app();
    app.switch_kind("deployments");
    let workload = expression_workload(true);
    apply(&mut app, workload.clone());
    app.table_state.select(Some(0));
    let requests = Arc::new(std::sync::Mutex::new(Vec::new()));
    let seen = requests.clone();
    app.cluster.client = kube::Client::new(
        tower::service_fn(move |request: http::Request<kube::client::Body>| {
            seen.lock().unwrap().push(request.uri().to_string());
            let response = if request.uri().path().ends_with("/pods") {
                json!({"apiVersion":"v1","kind":"PodList","metadata":{},"items":[]})
            } else if request.uri().path().ends_with("/web") {
                workload.clone()
            } else {
                json!({"apiVersion":"v1","kind":"EventList","metadata":{},"items":[]})
            };
            async move {
                Ok::<_, std::convert::Infallible>(http::Response::new(http_body_util::Full::new(
                    hyper::body::Bytes::from(response.to_string()),
                )))
            }
        }),
        "default",
    );
    app.handle_key(press(KeyCode::Char('X'))).unwrap();
    tokio::time::timeout(std::time::Duration::from_secs(5), async {
        loop {
            if matches!(rx.recv().await, Some(Msg::Explain { .. })) {
                break;
            }
        }
    })
    .await
    .unwrap();
    let requests = requests.lock().unwrap();
    let pods = requests
        .iter()
        .find(|uri| uri.contains("/pods?"))
        .expect("owned pods requested");
    let params: std::collections::HashMap<_, _> =
        form_urlencoded::parse(pods.split_once('?').unwrap().1.as_bytes())
            .into_owned()
            .collect();
    assert_eq!(
        params.get("labelSelector").map(String::as_str),
        Some("app=web,tier in (api,frontend),environment notin (test),enabled,!disabled")
    );
}

type HealthResponses = Arc<std::sync::Mutex<HashMap<String, (u16, serde_json::Value)>>>;

fn health_report_app(
    plural: &str,
    resource: serde_json::Value,
) -> (
    App,
    Receiver<Msg>,
    HealthResponses,
    Arc<std::sync::Mutex<Vec<String>>>,
) {
    let (app, rx) = test_app();
    health_report_app_with(app, rx, plural, resource)
}

fn health_report_app_with(
    mut app: App,
    rx: Receiver<Msg>,
    plural: &str,
    resource: serde_json::Value,
) -> (
    App,
    Receiver<Msg>,
    HealthResponses,
    Arc<std::sync::Mutex<Vec<String>>>,
) {
    app.switch_kind(plural);
    apply(&mut app, resource);
    app.table_state.select(Some(0));
    let responses: HealthResponses = Arc::default();
    let requests = Arc::new(std::sync::Mutex::new(Vec::new()));
    let replies = responses.clone();
    let seen = requests.clone();
    app.cluster.client = kube::Client::new(
        tower::service_fn(move |request: http::Request<kube::client::Body>| {
            assert_eq!(request.method(), http::Method::GET);
            let path = request.uri().path().to_owned();
            seen.lock().unwrap().push(path.clone());
            let (code, response) = replies.lock().unwrap().get(&path).cloned().unwrap_or_else(
                || {
                    if path.ends_with("/namespaces") {
                        (200, json!({"apiVersion":"v1","kind":"NamespaceList","metadata":{},"items":[]}))
                    } else if path.ends_with("/events") {
                        (
                            200,
                            json!({"apiVersion":"v1","kind":"EventList","metadata":{},"items":[]}),
                        )
                    } else if path.ends_with("/pods") {
                        (
                            200,
                            json!({"apiVersion":"v1","kind":"PodList","metadata":{},"items":[]}),
                        )
                    } else {
                        panic!("unexpected report GET {path}")
                    }
                },
            );
            async move {
                Ok::<_, std::convert::Infallible>(
                    http::Response::builder()
                        .status(code)
                        .body(http_body_util::Full::new(hyper::body::Bytes::from(
                            response.to_string(),
                        )))
                        .unwrap(),
                )
            }
        }),
        "default",
    );
    (app, rx, responses, requests)
}

fn open_health_report_key(app: &mut App, gitops: bool) {
    if gitops {
        app.handle_key(press(KeyCode::Char(':'))).unwrap();
        for key in "gitops".chars() {
            app.handle_key(press(KeyCode::Char(key))).unwrap();
        }
        app.handle_key(press(KeyCode::Enter)).unwrap();
    } else {
        app.handle_key(press(KeyCode::Char('X'))).unwrap();
    }
}

async fn receive_health_report(app: &mut App, rx: &mut Receiver<Msg>, gitops: bool) {
    tokio::time::timeout(std::time::Duration::from_secs(5), async {
        while let Some(message) = rx.recv().await {
            let report = if gitops {
                matches!(message, Msg::Gitops { .. })
            } else {
                matches!(message, Msg::Explain { .. })
            };
            if report {
                app.handle_msg(message);
                break;
            }
        }
    })
    .await
    .expect("health report did not finish");
}

#[tokio::test]
async fn explain_refresh_reads_current_resource_without_watch_updates() {
    let root = expression_workload(true);
    let (mut app, mut rx, responses, requests) = health_report_app("deployments", root.clone());
    let path = "/apis/apps/v1/namespaces/default/deployments/web";
    responses
        .lock()
        .unwrap()
        .insert(path.into(), (200, root.clone()));
    open_health_report_key(&mut app, false);
    receive_health_report(&mut app, &mut rx, false).await;
    assert!(
        app.explain_items
            .iter()
            .any(|finding| finding.text.contains("is healthy"))
    );
    let mut fresh = root;
    fresh["status"]["readyReplicas"] = json!(0);
    responses.lock().unwrap().insert(path.into(), (200, fresh));
    app.handle_key(press(KeyCode::Char('r'))).unwrap();
    receive_health_report(&mut app, &mut rx, false).await;
    assert!(
        app.explain_items
            .iter()
            .any(|finding| finding.text.contains("is unavailable"))
    );
    assert_eq!(
        app.explain_source.as_ref().unwrap().data["status"]["readyReplicas"],
        0
    );
    assert_eq!(
        requests
            .lock()
            .unwrap()
            .iter()
            .filter(|request| *request == path)
            .count(),
        2
    );
}

#[tokio::test]
async fn gitops_refresh_reads_current_owner_and_source_reference() {
    let root = json!({"apiVersion":"kustomize.toolkit.fluxcd.io/v1","kind":"Kustomization",
        "metadata":{"name":"web","namespace":"default","uid":"owner-uid"},
        "spec":{"sourceRef":{"kind":"GitRepository","name":"old-source"}},
        "status":{"conditions":[{"type":"Ready","status":"True"}]}});
    let (mut app, mut rx, responses, requests) = health_report_app("kustomizations", root.clone());
    let kind = app.kind.as_ref().unwrap();
    let path = format!(
        "/apis/{}/namespaces/default/kustomizations/web",
        kind.ar.api_version
    );
    app.cluster.register_kind(
        "source.toolkit.fluxcd.io",
        "GitRepository",
        "gitrepositories",
        true,
    );
    let source_kind = app.cluster.resolve("gitrepositories").unwrap();
    let source_path = format!(
        "/apis/{}/namespaces/default/gitrepositories",
        source_kind.ar.api_version
    );
    {
        let mut replies = responses.lock().unwrap();
        replies.insert(path.clone(), (200, root.clone()));
        for name in ["old-source", "new-source"] {
            replies.insert(format!("{source_path}/{name}"), (200, json!({"apiVersion":source_kind.ar.api_version,"kind":"GitRepository","metadata":{"name":name,"namespace":"default"},"status":{"conditions":[{"type":"Ready","status":"True"}]}})));
        }
    }
    open_health_report_key(&mut app, true);
    receive_health_report(&mut app, &mut rx, true).await;
    let mut fresh = root;
    fresh["status"]["conditions"][0]["status"] = json!("False");
    fresh["spec"]["sourceRef"]["name"] = json!("new-source");
    responses.lock().unwrap().insert(path.clone(), (200, fresh));
    app.handle_key(press(KeyCode::Char('r'))).unwrap();
    receive_health_report(&mut app, &mut rx, true).await;
    assert!(
        app.gitops_items
            .iter()
            .any(|finding| finding.text.contains("Ready: False"))
    );
    assert_eq!(
        app.gitops_source.as_ref().unwrap().data["spec"]["sourceRef"]["name"],
        "new-source"
    );
    let requests = requests.lock().unwrap();
    assert_eq!(
        requests.iter().filter(|request| **request == path).count(),
        2
    );
    assert!(requests.contains(&format!("{source_path}/new-source")));
}

/// What the fleet dashboard counts against a cluster. A status Argo has not
/// filled in yet is a new Application, not a fault.
#[test]
fn fleet_counts_drifted_and_unhealthy_applications_only() {
    let app = |sync: &str, health: &str| {
        let mut status = json!({});
        if !sync.is_empty() {
            status["sync"] = json!({"status": sync});
        }
        if !health.is_empty() {
            status["health"] = json!({"status": health});
        }
        let value = json!({"apiVersion": "argoproj.io/v1alpha1", "kind": "Application",
                           "metadata": {"name": "a", "namespace": "argocd"}, "status": status});
        serde_json::from_value::<DynamicObject>(value).expect("valid Application")
    };
    assert!(!super::fleet::application_degraded(&app(
        "Synced", "Healthy"
    )));
    assert!(super::fleet::application_degraded(&app(
        "OutOfSync",
        "Healthy"
    )));
    assert!(super::fleet::application_degraded(&app(
        "Synced", "Degraded"
    )));
    assert!(super::fleet::application_degraded(&app(
        "Synced", "Missing"
    )));
    assert!(super::fleet::application_degraded(&app(
        "Synced", "Unknown"
    )));
    // A rollout in flight is not a fault, and it flaps.
    assert!(!super::fleet::application_degraded(&app(
        "Synced",
        "Progressing"
    )));
    // Not yet compared by Argo, also not a fault.
    assert!(!super::fleet::application_degraded(&app("", "")));
}

/// The fleet count pages rather than pulling every Application at once, so it
/// has to follow `continue` to the end and total across pages.
#[tokio::test]
async fn fleet_application_count_follows_every_page() {
    let application = |name: &str, sync: &str| {
        json!({"apiVersion": "argoproj.io/v1alpha1", "kind": "Application",
               "metadata": {"name": name, "namespace": "argocd"},
               "status": {"sync": {"status": sync}, "health": {"status": "Healthy"}}})
    };
    let page = |items: Vec<serde_json::Value>, next: Option<&str>| {
        let mut meta = json!({});
        if let Some(token) = next {
            meta["continue"] = json!(token);
        }
        json!({"apiVersion": "argoproj.io/v1alpha1", "kind": "ApplicationList",
               "metadata": meta, "items": items})
    };
    // Two drifted on page one, one on page two, none on the last.
    let pages = [
        page(
            vec![
                application("a", "OutOfSync"),
                application("b", "Synced"),
                application("c", "OutOfSync"),
            ],
            Some("page-2"),
        ),
        page(
            vec![application("d", "OutOfSync"), application("e", "Synced")],
            Some("page-3"),
        ),
        page(vec![application("f", "Synced")], None),
    ];

    let served = Arc::new(std::sync::Mutex::new(0usize));
    let tokens = Arc::new(std::sync::Mutex::new(Vec::<String>::new()));
    let seen = served.clone();
    let asked = tokens.clone();
    let client = kube::Client::new(
        tower::service_fn(move |request: http::Request<kube::client::Body>| {
            let query = request.uri().query().unwrap_or_default().to_string();
            asked.lock().unwrap().push(query);
            let index = {
                let mut n = seen.lock().unwrap();
                let i = *n;
                *n += 1;
                i
            };
            let body = serde_json::to_vec(&pages[index]).unwrap();
            async move {
                Ok::<_, std::convert::Infallible>(
                    http::Response::builder()
                        .status(200)
                        .body(kube::client::Body::from(body))
                        .unwrap(),
                )
            }
        }),
        "default",
    );

    let (app, _rx) = test_app();
    let kind = app
        .cluster
        .resolve_in_group("Application", "argoproj.io")
        .expect("Application kind");
    let mut warn = None;
    let count = super::fleet::count_degraded_applications(&client, &kind.ar, &mut warn).await;

    assert_eq!(count, Some(3));
    assert!(warn.is_none(), "{warn:?}");
    let asked = tokens.lock().unwrap();
    assert_eq!(
        asked.len(),
        3,
        "should stop when continue is empty: {asked:?}"
    );
    assert!(asked[0].contains("limit=500"), "{asked:?}");
    assert!(asked[1].contains("continue=page-2"), "{asked:?}");
    assert!(asked[2].contains("continue=page-3"), "{asked:?}");
}

fn argocd_application(destination: serde_json::Value) -> serde_json::Value {
    json!({
        "apiVersion": "argoproj.io/v1alpha1", "kind": "Application",
        "metadata": {"name": "web", "namespace": "default", "uid": "app-uid"},
        "spec": {
            "project": "default",
            "source": {"repoURL": "https://github.com/example/repo", "path": "manifests",
                       "targetRevision": "HEAD"},
            "destination": destination,
            "syncPolicy": {"automated": {"prune": true}}
        },
        "status": {
            "sync": {"status": "OutOfSync", "revision": "53e28ff20cc530b9ada2173fbbd64d48338583ba"},
            "health": {"status": "Healthy"},
            "resources": [
                {"version": "v1", "kind": "Service", "namespace": "default", "name": "web",
                 "status": "OutOfSync", "health": {"status": "Healthy"}}
            ]
        }
    })
}

fn open_argocd_view(app: &mut App) {
    app.handle_key(press(KeyCode::Char(':'))).unwrap();
    for key in "argocd".chars() {
        app.handle_key(press(KeyCode::Char(key))).unwrap();
    }
    app.handle_key(press(KeyCode::Enter)).unwrap();
}

async fn receive_argocd_report(app: &mut App, rx: &mut Receiver<Msg>) {
    tokio::time::timeout(std::time::Duration::from_secs(5), async {
        while let Some(message) = rx.recv().await {
            if matches!(message, Msg::Argocd { .. }) {
                app.handle_msg(message);
                break;
            }
        }
    })
    .await
    .expect("argocd report did not finish");
}

/// An Application deploying into the cluster we are connected to lists what it
/// manages, and `⏎` opens the managed object.
#[tokio::test]
async fn argocd_view_lists_managed_resources_and_jumps_to_one() {
    let root = argocd_application(json!({"server": "https://kubernetes.default.svc",
                                         "namespace": "default"}));
    let (mut app, mut rx, responses, _) = health_report_app("applications", root.clone());
    let kind = app.kind.as_ref().unwrap();
    let path = format!(
        "/apis/{}/namespaces/default/applications/web",
        kind.ar.api_version
    );
    responses.lock().unwrap().insert(path, (200, root));

    open_argocd_view(&mut app);
    receive_argocd_report(&mut app, &mut rx).await;

    assert_eq!(app.mode, Mode::Argocd);
    let texts: Vec<&str> = app.argocd_items.iter().map(|f| f.text.as_str()).collect();
    assert!(texts.contains(&"Application/web: OutOfSync / Healthy"));
    assert!(texts.contains(&"Managed resources (1)"));
    assert!(texts.contains(&"Service/web: OutOfSync / Healthy"));
    assert!(texts.contains(&"Service/web is OutOfSync"));
    assert!(texts.contains(&"destination this cluster/default"));

    app.handle_key(press(KeyCode::Enter)).unwrap();
    assert_eq!(app.mode, Mode::Table);
    assert_eq!(app.kind_plural, "services");
    assert_eq!(app.fields.as_deref(), Some("metadata.name=web"));
}

/// The correctness guarantee: an Application deploying somewhere else must not
/// offer a jump that would resolve against this cluster.
#[tokio::test]
async fn argocd_view_will_not_jump_into_a_remote_destination() {
    let root = argocd_application(json!({"server": "https://other.example:6443",
                                         "namespace": "default"}));
    let (mut app, mut rx, responses, _) = health_report_app("applications", root.clone());
    let kind = app.kind.as_ref().unwrap();
    let path = format!(
        "/apis/{}/namespaces/default/applications/web",
        kind.ar.api_version
    );
    responses.lock().unwrap().insert(path, (200, root));

    open_argocd_view(&mut app);
    receive_argocd_report(&mut app, &mut rx).await;

    assert!(app.argocd_items.iter().all(|f| f.target.is_none()));
    let texts: Vec<&str> = app.argocd_items.iter().map(|f| f.text.as_str()).collect();
    assert!(texts.contains(&"destination https://other.example:6443/default"));

    app.argocd_state.select(Some(
        app.argocd_items
            .iter()
            .position(|f| f.text.starts_with("Service/web:"))
            .expect("managed resource line"),
    ));
    app.handle_key(press(KeyCode::Enter)).unwrap();
    assert_eq!(app.mode, Mode::Argocd, "must not navigate");
    assert!(
        app.flash.contains("no kubeconfig context serves"),
        "{}",
        app.flash
    );
}

